```ts
import lockfile from "proper-lockfile";

export async function bumpCounterSafe(path: string): Promise<number> {
  // ensure file exists so we can open/lock it
  const fh = fs.openSync(path, "a"); fs.closeSync(fh); // touch
  const release = await lockfile.lock(path, { retries: { retries: 10, minTimeout: 5, maxTimeout: 50 } });
  try {
    let n = parseInt(fs.readFileSync(path, "utf8"), 10) || 0;
    n += 1;
    fs.writeFileSync(path, String(n));
    return n;
  } finally {
    await release();
  }
}
```
Note: parseInt("") is NaN → NaN||0 = 0 good. But careful: if file contains "0"? fine.

proper-lockfile locks by creating `<path>.lock` directory — mkdir is atomic on POSIX, so it's a correct advisory lock.

