result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/counterfile.ts", "content": "import fs from "node:fs";
import { lock, type ReleaseFn } from "proper-lockfile";

/**
 * UNSAFE for concurrent use.
 *
 * This performs a non-atomic read-modify-write: between the
 * `readFileSync` and `writeFileSync` below, another process or worker
 * thread can read the same stale value, delete the file, or write its
 * own count. Two callers can then both compute the same increment and
 * one update is silently lost (lost-update anomaly).
 *
 * Demonstrated by src/a.test.ts + src/b.test.ts racing on a shared
 * hard-coded path under vitest's parallel test-file workers.
 */
export function bumpCounter(path: string): number {
  let n = 0;
  if (fs.existsSync(path)) n = parseInt(fs.readFileSync(path, "utf8"), 10);
  n += 1;
  fs.writeFileSync(path, String(n));
  return n;
}

/**
 * Concurrency-safe variant.
 *
 * Uses an advisory lock (proper-lockfile), which is atomically acquired
 * via mkdir(2) of `<file>.lock` — atomic on POSIX and Windows. The
 * critical section (read -> increment -> write) is serialized across
 * processes/workers. Callers must go through this function for the
 * guarantee to hold; it cannot protect against writers that ignore
 * the lock (that is inherent to *advisory* locking).
 */
export async function bumpCounterSafe(path: string): Promise<number> {
  // Ensure the target exists so we have something to lock around.
  // 'a' flag creates the file if missing without truncating content.
  fs.closeSync(fs.openSync(path, "a"));

  const release: ReleaseFn = await lock(path, {
    realpath: false,
    retries: { retries: 10, minTimeout: 5, maxTimeout: 100 },
  });
  try {
    let n = parseInt(fs.readFileSync(path, "utf8"), 10);
    if (Number.isNaN(n)) n = 0;
    n += 1;
    fs.writeFileSync(path, String(n));
    return n;
  } finally {
    await release();
  }
}
"})
